def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_my = my[-1]
    last_op = op[-1]
    opD = op.count('D')
    recent_opD = op[-10:].count('D')

    unprov = 0
    cd = 0
    for i in range(n):
        if op[i] == 'D':
            if i == 0 or my[i - 1] == 'C':
                unprov += 1
            if my[i] == 'C':
                cd += 1

    if n <= 5 and opD == n:
        return 'D'

    chronic = False
    lookback = n if n < 10 else 10
    if n >= 6:
        if unprov >= 3 and recent_opD >= 3:
            chronic = True
        if cd >= 3 and recent_opD >= 4:
            chronic = True
        if n >= 15 and opD * 2 >= n and recent_opD >= 5:
            chronic = True
        if lookback >= 5 and recent_opD == lookback:
            chronic = True

    if chronic:
        return 'D'

    if last_op == 'D':
        if n >= 2:
            if last_my == 'C' and my[-2] == 'D' and op[-2] == 'C':
                if unprov <= 1 and recent_opD <= 3:
                    return 'C'
            if last_my == 'D' and my[-2] == 'D' and op[-2] == 'D':
                if unprov <= 1 and cd <= 1 and recent_opD <= 3:
                    return 'C'
        return 'D'

    return 'C'
